records = []
for index, item in enumerate(items, start=1):
    if index in CHOCOLATE_OVERRIDES:
        item = CHOCOLATE_OVERRIDES[index]
    dish_id = f"hk-dish-{index:04d}"
    ingredients_text = ", ".join(item["ingredients"])
    image_path = f"images/{dish_id}-{item['slug']}.png"
    yue = f"{item['zh']}{YUE_BY_SUBCATEGORY[item['subcategory']]}"
    prompt = "\n".join([
        "Use case: product-mockup",
        "Asset type: square dim-sum catalog food photograph",
        f"Primary request: an original, appetizing photograph of {item['en']} ({item['zh']}), featuring {ingredients_text}; present it as {item['presentation']}",
        "Scene/backdrop: warm Hong Kong tea-house tabletop of dark honey-toned wood, understated and uncluttered",
        f"Subject: only the specified {item['en']}; ingredients and traditional presentation must be visually accurate",
        "Style/medium: photorealistic natural food photography, premium but believable restaurant presentation",
        "Composition/framing: square 1:1, close three-quarter overhead view, dish centered, full serving visible, generous clean margins",
        "Lighting/mood: warm window light, soft natural shadows, inviting yum-cha atmosphere",
        "Color palette: natural ingredient colours, warm wood, restrained porcelain or bamboo serving ware",
        "Materials/textures: realistic food texture, natural wood grain, believable bamboo or porcelain",
        "Constraints: one distinct dish only; culturally accurate Hong Kong Cantonese presentation; no people; no hands; no text; no menus; no logos; no watermark; no decorative lettering",
        "Avoid: multiple dishes, plastic-looking food, excessive garnish, fusion styling, duplicate serving vessels, cropped dish, illustration, CGI",
    ])
    record = {
        "id": dish_id,
        "slug": item["slug"],
        "name": {"en": item["en"], "zhHant": item["zh"]},
        "jyutping": item["jyutping"],
        "category": item["category"],
        "subcategory": item["subcategory"],
        "description": {
            "en": f"{item['en']} is a {item['subcategory']} made with {ingredients_text} and served as {item['presentation']}.",
            "yue": yue,
        },
        "ingredients": item["ingredients"],
        "dietaryTags": item["dietary"],
        "allergens": item["allergens"],
        "image": {
            "path": image_path,
            "alt": {
                "en": f"Warm tea-house photograph of {item['en']}",
                "yue": f"港式茶樓木枱上嘅{item['zh']}",
            },
        },
        "imagePrompt": prompt,
    }
    if index in CHOCOLATE_OVERRIDES:
        record["chocolateFilled"] = True
    records.append(record)

if len(records) != 250:
    raise RuntimeError(f"Expected 250 records, got {len(records)}")

out = Path("dim-sum/catalog-parts/part-0001-0250.json")
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(records, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"wrote {len(records)} records to {out}")
